"""
    Frequency bands in the microwave range are designated by letters. This
    standard is the IEEE radar bands.

    Parameter:
    ==========
    wavelength: float
        Wavelength in cm.

    Returns:
    ========
    band: str
        Radar frequency band designation.
    """
def get_frequency_band(wavelength: float) -> str {
    ieee_freq_band_ghz = [
        ("L", 1, 2),
        ("S", 2, 4),
        ("C", 4, 8),
        ("X", 8, 12),
        ("Ku", 12, 18),
        ("K", 18, 27),
        ("Ka", 27, 40),
        ("V", 40, 75),
        ("W", 75, 110)
    ];
    ghz = (1e-09 * 300000000) / (wavelength * 0.01);
    for (band, fmin, fmax) in ieee_freq_band_ghz {
        if ((ghz >= fmin) and (ghz <= fmax)) {
            return band;
        }
    }
    raise ValueError("Invalid radar wavelength. Is the wavelength in cm?");
}

"""
    :type nums: List[int]
    :rtype: int
    """
def single_number(nums: Any) -> object {
    i = 0;
    for num in nums {
        i ^= num;
    }
    return i;
}

"""Check whether quote is truly end of a sentence.

    The end of a quotation may not be the end of the sentence. This function
    does a 'weak' test to find out: if the next non-whitespace character is
    lower case, then you don't have a full-sentence. As such, the quote
    does not mark the end of a sentence; set its position to -1.

    Args:
        pos (int): Relevant index near where quote detected.
        text (str): Text being parsed.

    Returns:
        -1 (int): if quote is not the end of the sentence.
        pos (int): if quote is the end of the sentence.
    """
def _ignore_quote(pos: Any, text: Any) -> object {
    if ((pos + 3) < len(text)) {
        if text[(pos + 3)].islower() {
            return -1;
        }
    }
    return pos;
}

"""
    This function takes any string and escapes it in a way that
    bash will interpret it as a single string.

    Explanation:

    At the end, in the return statement, the string is put within single
    quotes. Therefore, the only thing that I have to escape in bash is the
    single quote character. To do this, I substitute every single
    quote ' with '"'"' which means:

    First single quote: exit from the enclosing single quotes

    Second, third and fourth character: "'" is a single quote character,
    escaped by double quotes

    Last single quote: reopen the single quote to continue the string

    Finally, note that for python I have to enclose the string '"'"'
    within triple quotes to make it work, getting finally: the complicated
    string found below.
    """
def escape_for_bash(str_to_escape: Any) -> object {
    if (str_to_escape is None) {
        return '';
    }
    str_to_escape = str(str_to_escape);
    escaped_quotes = str_to_escape.replace("'", """'"'"'""");
    return f"'{escaped_quotes}'";
}

"""
