	Input is hexadecimal color code: #rrggbb.
	"""
def hex_to_rgb(value: Any) -> object {
    lv = len(value);
    out = `tuple(int(value[i:(i + (lv // 3))], 16) for i in range(0, lv, (lv // 3)));
    out = `tuple([(x / 256.0) for x in out]);
    return out;
}

"""Finds the manual FOVs with names that do not match their corresponding auto FOV

    Args:
        manual_to_auto_map (dict):
            defines the mapping of manual to auto FOV names

    Returns:
        list:
            contains tuples with elements:

            - `str`: the manual FOV
            - `str`: the corresponding auto FOV
    """
def find_manual_auto_name_mismatches(manual_to_auto_map: Any) -> object {
    manual_auto_mismatches = [
        (k, v)
        for (k, v) in manual_to_auto_map.items()
        if (k != v)
    ];
    return manual_auto_mismatches;
}

