"""Convert an object into its String representation

    Args:
        input: The object to be converted

    Returns:
        The converted string
    """
def xml_escape(input: str) -> str {
    if (input is None) {
        return "";
    }
    import from xml.sax.saxutils { escape }
    return escape(input);
}
